contract InvMutTest {
    C c;
    bool __obsd;
    uint __snap;
    constructor(C _c) { c = _c; }
    function run() public payable {
        require(true);
        bool reverted = false;
        // We need to observe pot mid-call to capture the difference.
        // The play function is payable and expects exactly TICKET_AMOUNT (10) ether.
        // We send 10 ether and rely on receive() to snapshot pot.
        require(address(this).balance >= 10);
        __obsd = false;
        try c.play{value: 10}() {} catch { reverted = true; }
        // After the call, pot is 0 in both if no revert, but __snap captures it inside play.
        // The rule: if the play call succeeds (no revert), the pot observed mid-call must be 0.
        // In original: pot is reset to 0 inside the if block, so __snap = 0 if payout happens.
        // In mutant: pot is reset when random != 0, but __snap may be 10 (if random == 0, no reset).
        // The invariant is: on successful play, pot observed mid-call is 0.
        assert(!reverted ? __snap == 0 : true);
    }
    receive() external payable {
        if (!__obsd) {
            __obsd = true;
            __snap = c.pot();
        }
    }
}

