pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    uint constant TICKET_AMOUNT = 10;
    uint constant FEE_AMOUNT = 1;
    uint public wins;
    uint public feesCollected;

    function setUp() public {
        c = new C();
        wins = 0;
        feesCollected = 0;
    }

    function testFuzz_property(uint8 playCount) public {
        // Bound to a reasonable number of plays to avoid out-of-gas, but keep it wide enough
        uint256 maxPlays = 50;
        uint256 plays = bound(uint256(playCount), 1, maxPlays);

        address player = address(0x1234);
        vm.deal(player, plays * TICKET_AMOUNT);
        vm.startPrank(player);

        for (uint256 i = 0; i < plays; i++) {
            // Simulate the randomness by checking if this play results in a win (random == 0)
            // We need to track wins without relying on randomness, which we cannot control.
            // Instead, we call play() and check the effect on pot and bank balance.
            // However, the fuzzer cannot control block.timestamp/block.difficulty randomness,
            // so we simply call play() multiple times. The property must hold regardless.
            // But we need to know the actual outcomes to track fees paid to bank.
            // We'll track the bank balance before and after each play.
            uint256 bankBefore = address(c.bank()).balance;
            c.play{value: TICKET_AMOUNT}();
            uint256 bankAfter = address(c.bank()).balance;
            if (bankAfter > bankBefore) {
                wins++;
                feesCollected += (bankAfter - bankBefore);
            }
        }

        vm.stopPrank();

        // Property: pot <= feesCollected (since each win transfers FEE_AMOUNT to bank,
        // and the contract should reset pot to 0 after a win. Thus the pot can never
        // exceed the total fees transferred out. The bug fails to reset pot, so on a
        // subsequent win the pot can be larger than feesCollected.)
        assertTrue(c.pot() <= feesCollected);
    }
}

