pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 timestamp, uint256 difficulty, uint256 actorSeed) public {
        // Bound timestamp and difficulty to reasonable ranges; actorSeed just for variety
        timestamp = bound(timestamp, 1, 2**40);
        difficulty = bound(difficulty, 1, 2**40);

        // Use a deterministic address derived from seed to avoid precompiles
        address actor = address(uint160(uint256(keccak256(abi.encode(actorSeed)))));
        vm.assume(actor != address(0) && actor != address(this) && actor != address(c));

        // Deal exactly the ticket amount so play() can be called once
        uint256 ticketAmount = 10;
        vm.deal(actor, ticketAmount);

        // Set block environment
        vm.warp(timestamp);
        vm.roll(difficulty);

        // Call play from the actor
        vm.prank(actor);
        c.play{value: ticketAmount}();

        // The general rule: after exactly one play() call, pot is either 0 or ticketAmount.
        // The reference resets pot to 0 when random == 0; the bug never resets (pot stays nonzero).
        // Thus the reference satisfies that pot is either 0 or ticketAmount, while the bug fails
        // when random == 0 (pot remains ticketAmount instead of 0). The fuzzer will find inputs
        // where random == 0, causing a violation of this property in the buggy version.
        assertTrue(c.pot() == 0 || c.pot() == ticketAmount);
    }
}
